using System;using System.IO;using System.Linq;using System.Text.Json;
class Test {
 static int checks;static void Check(bool b,string s){if(!b)throw new Exception(s);checks++;}
 static JsonElement Status(DebugRecords d)=>JsonDocument.Parse(JsonSerializer.Serialize(d.Status())).RootElement;
 static void Main(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);string home=Path.Combine(root,"home"),run=Path.Combine(root,"run");Directory.CreateDirectory(home);Directory.CreateDirectory(run);File.WriteAllText(Path.Combine(home,"device.json"),"do not remove");long now=1700000000000;Func<long> clock=()=>now;long duration=48L*60*60*1000;
 byte[] png=Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=");
 var d=new DebugRecords(home,run,clock);Check(!Status(d).GetProperty("enabled").GetBoolean(),"default off");d.Set(true);long deadline=Status(d).GetProperty("expiresAt").GetInt64();Check(deadline==now+duration,"48 hour duration");now+=100;d.Set(true);Check(Status(d).GetProperty("expiresAt").GetInt64()==deadline,"idempotent enable");var t=d.Begin();File.WriteAllBytes(t.image,png);d.Complete(t,new{label="test",unicode="café",response=new{psid="SECRET",token="SECRET2",matching=true},show=new{title=(string)null}});
 var files=Directory.GetFiles(Path.Combine(home,"debug-records"),"*.json");Check(files.Length==1,"one sidecar");string body=File.ReadAllText(files[0]);Check(!body.Contains("SECRET")&&body.Contains("redacted"),"redaction");Check(Directory.GetFiles(Path.Combine(home,"debug-records"),"*.png").Length==1,"PNG saved");Check(!File.Exists(t.image),"staging removed");File.Copy(Path.ChangeExtension(files[0],".png"),Path.Combine(root,"embedded.png"),true);File.Copy(files[0],Path.Combine(root,"embedded.json"),true);
 d=new DebugRecords(home,run,clock);Check(Status(d).GetProperty("expiresAt").GetInt64()==deadline,"restart preserves deadline");Check(Status(d).GetProperty("records").GetInt32()==1,"restart retains records");var pending=d.Begin();d.Set(false);File.WriteAllBytes(pending.image,png);d.Complete(pending,new{label="late write"});Check(!Directory.Exists(Path.Combine(home,"debug-records")),"stop purges directory");Check(!File.Exists(pending.image),"late completion removed");Check(File.Exists(Path.Combine(home,"device.json")),"unrelated configuration preserved");
 d.Set(true);var old=d.Begin();d.Set(false);d.Set(true);File.WriteAllBytes(old.image,png);d.Complete(old,new{label="previous session"});Check(Status(d).GetProperty("records").GetInt32()==0,"old session rejected");deadline=Status(d).GetProperty("expiresAt").GetInt64();var live=d.Begin();File.WriteAllBytes(live.image,png);d.Complete(live,new{label="will expire"});now=deadline;d.Maintain();Check(!Status(d).GetProperty("enabled").GetBoolean(),"expires without status or TV loop");Check(!Directory.Exists(Path.Combine(home,"debug-records")),"expiry purges pictures and events");
 d.Set(true);deadline=Status(d).GetProperty("expiresAt").GetInt64();now=deadline+1;d=new DebugRecords(home,run,clock);Check(!Status(d).GetProperty("enabled").GetBoolean(),"expired restart stays off");Check(!File.Exists(Path.Combine(home,"debug-session.json")),"deadline removed");
 d.Set(true);now-=10000;d.Maintain();Check(!Status(d).GetProperty("enabled").GetBoolean(),"backward clock cannot extend collection");
 var bounded=new DebugRecords(home,run,clock,2000);bounded.Set(true);for(int i=0;i<7;i++){now++;var b=bounded.Begin();File.WriteAllBytes(b.image,png);bounded.Complete(b,new{index=i});}Check(Status(bounded).GetProperty("bytes").GetInt64()<=2000,"storage bounded");Check(Status(bounded).GetProperty("evictedRecords").GetInt64()>0,"old records evicted");bounded.Set(false);
 File.WriteAllText(Path.Combine(home,"debug-session.json"),"invalid json");Directory.CreateDirectory(Path.Combine(home,"debug-records"));File.WriteAllText(Path.Combine(home,"debug-records","orphan.tmp"),"x");d=new DebugRecords(home,run,clock);Check(!Directory.Exists(Path.Combine(home,"debug-records")),"corrupt state clears orphan files");
 d.Set(true);var invalid=d.Begin();File.WriteAllText(invalid.image,"not a PNG");d.Complete(invalid,new{label="invalid"});files=Directory.GetFiles(Path.Combine(home,"debug-records"),"*.json");Check(files.Length==1,"failed image retains metadata");Check(!JsonDocument.Parse(File.ReadAllText(files[0])).RootElement.GetProperty("imageAvailable").GetBoolean(),"invalid PNG flagged");d.Set(false);
 Console.WriteLine(checks+" debug lifecycle checks passed");
 }
}
